use std::num::ParseIntError;

pub fn parse_pos(s: &str) -> Result<u32, ParseIntError> {
    s.parse::<u32>()
}

pub fn is_pos(s: &str) -> bool {
    parse_pos(s).map(|n| n > 0).unwrap_or(false)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_valid() {
        assert_eq!(parse_pos("5").unwrap_or(0), 5);
    }

    #[test]
    fn rejects_invalid() {
        assert!(!is_pos("abc"));
    }

    #[test]
    fn zero_is_not_positive() {
        assert!(!is_pos("0"));
    }
}
